TYPE File = ^ Élément ;

Élément = ENREGISTREMENT

  Info : Entier ;

  Suivant : File ;

FIN ;

Procédure Enfiler :

PROCÉDURE Enfiler(E/S Tête, Queue : File ; E Valeur : Entier)

VAR Nouveau : File ;

DÉBUT

  ALLOUER(Nouveau) ;

  Nouveau^.Info <- Valeur ;

  Nouveau^.Suivant <- NIL ;

  SI (Tête = NIL) ALORS

    Tête <- Nouveau ;

  SINON

    Queue^.Suivant <- Nouveau ;

  FIN SI ;

  Queue <- Nouveau ;

FIN ;

Procédure Défiler :

PROCÉDURE Défiler(E/S Tête, Queue : File ; S Valeur : Entier) ;

VAR Temp : Liste ;

DÉBUT

  SI (Tête <> NIL) ALORS

    Valeur <- Tête^.Info ;

    Temp <- Tête ;

    Tête <- Tête^.Suivant ;

    LIBÉRER(Temp) ;

    SI (Tête = NIL) ALORS

      Queue <- NIL ;

    FIN SI ;

  FIN SI ;

FIN ;

TYPE Pile = ^ Élément

Élément = ENREGISTREMENT

  Info : Entier ;

  Suivant : Pile ;

FIN ;

Procédure Empiler :

PROCÉDURE Empiler(E/S Sommet : Pile ; E Valeur : Entier) ;

VAR Nouveau : Pile ;

DÉBUT

  ALLOUER(Nouveau) ;

  Nouveau^.Info <- Valeur ;

  Nouveau^.Suivant <- Sommet ;

  Sommet <- Nouveau ;

FIN ;

Procédure Dépiler :

PROCÉDURE Dépiler(E/S Sommet : Pile)

VAR Temp : Pile ;

DÉBUT

  SI (Sommet <> NIL) ALORS

    Temp <- Sommet ;

    Sommet <- Sommet^.Suivant ;

    LIBÉRER(Temp) ;

  FIN SI ;

FIN ;

Fonction SommetPile :

FONCTION SommetPile(Sommet : Pile) : Entier ;

DÉBUT

  SI (NON (PileVide(Sommet))) ALORS

    SommetPile <- Sommet^.Info ;

  SINON

    SommetPile <- 0 ; // Valeur particulière

  FIN SI ;

FIN ;

Procédure InitPile :

PROCÉDURE InitPile(S Sommet : Pile)

DÉBUT

  Sommet <- NIL ;

FIN ;

Fonction PileVide :

FONCTION PileVide(E Sommet : Pile) : Booléen

DÉBUT

  SI (Sommet = NIL) ALORS

    PileVide <- Vrai ;

  SINON

    PileVide <- Faux ;

  FIN SI ;

FIN ;
